#include "Music/SongGuitar.h"
#include <iostream>
int main(){try{wingman::HarmonicResult song;song.regions={{.5,1.75,.9,*wingman::parseChord("C")},{2,4,.9,*wingman::parseChord("Am")}};wingman::GuitarSettings settings;settings.humanize=false;auto notes=wingman::guitarFromSong(song,settings,120);if(notes.empty()||settings.bars!=2)return 1;int checks=0;for(const auto& n:notes){const double start=n.beat*.5,end=(n.beat+n.duration)*.5;bool first=start>=.5&&start<1.75;if(!first&&!(start>=2&&start<4))return 2;if(end>(first?1.75:4)+.00001)return 3;auto chord=wingman::parseChord(first?"C":"Am")->notes();if(!std::any_of(chord.begin(),chord.end(),[&](int note){return note%12==n.note%12;}))return 4;++checks;}bool cancelled=false;try{wingman::guitarFromSong(song,settings,120,[]{return false;});}catch(...){cancelled=true;}if(!cancelled)return 5;std::cout<<checks<<" timeline-aligned guitar checks passed\n";}catch(const std::exception& e){std::cerr<<e.what();return 6;}}
